# Count markers per region
markers = [(1, 3), (3, 3), (3, 6), (3, 12), (6, 13), (7, 3), (7, 8), (10, 7), (11, 0), (11, 12), (13, 1), (13, 11), (15, 0), (15, 10), (17, 7), (18, 10)]

# Row regions: 0-3 (4 rows), 5-7 (3 rows), 9-12 (4 rows), 14-18 (5 rows) - dividers at 4, 8, 13
# Col regions: 0-3 (4 cols), 5-8 (4 cols), 10-13 (4 cols) - dividers at 4, 9

def get_region(r, c):
    if r in [4, 8, 13]:  # divider row
        return (2, 2)  # treat as such
    if c in [4, 9]:  # divider col  
        return (2, 2)
    row_reg = -1
    if r <= 3:
        row_reg = 0
    elif r <= 7:
        row_reg = 1
    elif r <= 12:
        row_reg = 2
    else:
        row_reg = 3
    col_reg = -1
    if c <= 3:
        col_reg = 0
    elif c <= 8:
        col_reg = 1
    else:
        col_reg = 2
    return (row_reg, col_reg)

from collections import Counter
region_counts = Counter()
for (r,c) in markers:
    reg = get_region(r, c)
    region_counts[reg] += 1

print(f"Region counts: {region_counts}")

# Which regions have 0 markers?
all_empty = True
for r in range(4):
    for c in range(3):
        count = region_counts.get((r,c), 0)
        if count == 0:
            print(f"Region ({r},{c}) has 0 markers")
        if count > 0:
            print(f"Region ({r},{c}) has {count} markers")

from collections import Counter
markers = [(1, 3), (3, 3), (3, 6), (3, 12), (6, 13), (7, 3), (7, 8), (10, 7), (11, 0), (11, 12), (13, 1), (13, 11), (15, 0), (15, 10), (17, 7), (18, 10)]
div_row = [4, 8, 13]
div_col = [4, 9]

# Count markers on each divider
on_div_row = {}
for dr in div_row:
    on_div_row[dr] = [m for m in markers if m[0] == dr]

on_div_col = {}
for dc in div_col:
    on_div_col[dc] = [m for m in markers if m[1] == dc]

for dr, rests in on_div_row.items():
    print(f"On row {dr}: {rests}")
for dc, rests in on_div_col.items():
    print(f"On col {dc}: {rests}")

# Markers that are at intersections (both row and col dividers) - unlikely
both = [m for m in markers if m[0] in div_row and m[1] in div_col]
print(f"Both: {both}")

